#!/bin/bash
set -eu
echo "=== Deploy skykin_inbound.lua (true longest-idle) ==="
python3 -c "import base64; open('/tmp/skykin_inbound.lua','wb').write(base64.b64decode(''))"
docker cp /tmp/skykin_inbound.lua skykin-freeswitch:/etc/freeswitch/scripts/skykin_inbound.lua
mkdir -p /opt/skykin/fs-live /root/skykin-fs-etc/scripts
cp /tmp/skykin_inbound.lua /opt/skykin/fs-live/skykin_inbound.lua
cp /tmp/skykin_inbound.lua /opt/skykin/fs-config/skykin_inbound.lua 2>/dev/null || true
cp /tmp/skykin_inbound.lua /root/skykin-fs-etc/scripts/skykin_inbound.lua 2>/dev/null || true
echo "=== Verify longest-idle fix ==="
docker exec skykin-freeswitch grep -n "agent_idle_stamp\|skykin_agent_idle\|True longest-idle" /etc/freeswitch/scripts/skykin_inbound.lua | head -20
echo
echo "DONE — no FS restart needed."
echo "After inbound calls:"
echo "  docker exec skykin-freeswitch sh -c 'grep "skykin longest-idle order" /var/log/freeswitch/freeswitch.log | tail -10'"
echo "Expect different r=/h=/idle= values (not all 1789457761)."
